const BASIC_CROPS=[{"n": 1, "page": 1, "width": 1105, "height": 110, "src": "data:image/webp;base64,"}, {"n": 2, "page": 1, "width": 1105, "height": 97, "src": "data:image/webp;base64,"}, {"n": 3, "page": 1, "width": 1105, "height": 160, "src": "data:image/webp;base64,"}, {"n": 4, "page": 1, "width": 1105, "height": 149, "src": "data:image/webp;base64,"}, {"n": 5, "page": 1, "width": 1105, "height": 269, "src": "data:image/webp;base64,"}, {"n": 6, "page": 1, "width": 1105, "height": 427, "src": "data:image/webp;base64,"}, {"n": 7, "page": 2, "width": 1105, "height": 120, "src": "data:image/webp;base64,"}, {"n": 8, "page": 2, "width": 1105, "height": 266, "src": "data:image/webp;base64,"}, {"n": 9, "page": 2, "width": 1105, "height": 159, "src": "data:image/webp;base64,"}, {"n": 10, "page": 2, "width": 1105, "height": 228, "src": "data:image/webp;base64,"}, {"n": 11, "page": 2, "width": 1105, "height": 40, "src": "data:image/webp;base64,"}, {"n": 12, "page": 2, "width": 1105, "height": 99, "src": "data:image/webp;base64,"}, {"n": 13, "page": 2, "width": 1105, "height": 344, "src": "data:image/webp;base64,"}, {"n": 14, "page": 3, "width": 1105, "height": 271, "src": "data:image/webp;base64,"}, {"n": 15, "page": 3, "width": 1105, "height": 382, "src": "data:image/webp;base64,"}, {"n": 16, "page": 3, "width": 1105, "height": 531, "src": "data:image/webp;base64,"}, {"n": 17, "page": 3, "width": 1105, "height": 38, "src": "data:image/webp;base64,"}, {"n": 18, "page": 4, "width": 1105, "height": 201, "src": "data:image/webp;base64,"}, {"n": 19, "page": 4, "width": 1105, "height": 150, "src": "data:image/webp;base64,"}, {"n": 20, "page": 4, "width": 1105, "height": 533, "src": "data:image/webp;base64,"}, {"n": 21, "page": 5, "width": 1105, "height": 444, "src": "data:image/webp;base64,"}, {"n": 22, "page": 5, "width": 1105, "height": 463, "src": "data:image/webp;base64,"}, {"n": 23, "page": 6, "width": 1105, "height": 360, "src": "data:image/webp;base64,"}, {"n": 24, "page": 6, "width": 1105, "height": 228, "src": "data:image/webp;base64,"}];
const BASIC_SOLUTIONS=[["二次函数定义","B","先化简，再判断能否写成 ax²+bx+c（a≠0）。B：2x(x−3)=2x²−6x，是二次函数。A 未限制 a≠0；C 的 x 在分母中；D 展开后为 −4x+4，是一次函数。","不能只看式子里有没有 x²；要先合并同类项。"],["顶点式与对称轴","A，直线 x=3","y=2(x−3)²+7，令括号 x−3=0，得到 x=3；顶点是 (3,7)，对称轴是竖直直线 x=3。","对称轴写 x=常数，不能写成一个点。"],["图象平移","A，y=(x−1)²−5","原顶点 (−1,−2)，右移2后为 (1,−2)，再下移3得到 (1,−5)。开口系数仍为1，所以新式为 y=(x−1)²−5。也可在原式中用 x−2 替换 x，再减3。","用顶点位置核对左右平移，避免只背符号。"],["开口、最值与增减性","B","a=1>0，开口向上；顶点 (2,1)，对称轴 x=2，最小值为1。对称轴右侧（含端点可写 x≥2）y随x增大而增大。A方向错，C把最小值当最大值，D对称轴符号错。","括号内变号读 h，括号外直接读 k。"],["图象判断系数符号","B，第二象限","由图开口向下，a<0；与y轴交点在正半轴，c>0。对称轴 −b/(2a)>0，结合 a<0 得 b>0。因此点 (a,b+c) 横坐标负、纵坐标正，在第二象限。","先分别确定两个坐标的符号，再判断象限。"],["二次函数与一次函数共用参数","C","直线 y=mx+m=m(x+1) 必过 (−1,0)，先排除不满足该点的 A、D。B 中直线递减说明 m<0，但抛物线顶点 (m,0) 在y轴右侧要求 m>0，矛盾。C 中直线递增、顶点在右侧，都要求 m>0，一致。","同一个字母 m 在两条函数中必须取同一个值。"],["限定区间的最值","B，−1/4≤y≤2","配方：y=(x−3/2)²−1/4。顶点横坐标3/2在[1,3]内，所以最小值−1/4能够取到。端点 y(1)=0、y(3)=2，最大值2。","先看顶点是否在区间内，再比较两端点。"],["数值表与对称性","A，0<x<4","x=1与3的函数值都为2，对称轴 x=(1+3)/2=2。表中 y(2)=0，且 y(1)=2，可得 y=2(x−2)²，开口向上。y(0)=8，与其对称的位置x=4也有y=8；低于8的部分在两者之间。","y<8 是严格不等式，边界0和4不取。"],["对称性与函数值比较","D，y₁=y₂>y₃","配方 y=−(x−1)²+c+1，对称轴 x=1，开口向下。−1与3离轴都是2，函数值相等；5离轴为4，开口向下时离轴越远函数值越小。","比较到对称轴的距离，不直接比较x大小。"],["联立方程与两根之和","A","联立 a(x−h)²+k=mx+n，整理为 ax²−(2ah+m)x+ah²+k−n=0。两根之和 x₁+x₂=(2ah+m)/a=2h+m/a。A中a、m都负，m/a>0，故根和>2h。B中m/a<0，错误。C只能推出a、m同号，未必都正；D只能推出异号，未必a正m负。","这是两根之和的应用；基础尚不熟时可稍后讲。"],["一般式配方求顶点","(1,4)","y=2(x²−2x)+6=2[(x−1)²−1]+6=2(x−1)²+4。因此顶点 (1,4)，对称轴 x=1。","括号内减去的1也要乘外面的2。"],["等高两点求对称轴","直线 x=2","A(−1,−1)、B(5,−1)纵坐标相同，它们关于抛物线的对称轴对称。对称轴横坐标为两点横坐标平均数：(−1+5)/2=2。原题括号里的 a≠0 是多余标注，因为x²系数已为1。","等高两点求中点，坐标符号要带上。"],["实际问题：落地对应y=0","10 m","落地时高度y=0：−(x−4)²/12+3=0，得到 (x−4)²=36，故 x−4=±6，x=10或−2。水平距离不能为负，舍去−2，推出距离10m。","要结合实际范围舍根，不能只取正平方根。"],["篱笆面积与实际范围","72 m²","设垂直墙的边AB=x。两侧与中间隔栏共3条长x的篱笆，另一横边长30−3x。面积S=x(30−3x)=−3(x−5)²+75。靠墙边不能超过12：0<30−3x≤12，故6≤x<10。理论顶点x=5不在允许范围；x≥6时面积递减，故x=6时最大，为6×12=72。","不能直接取理论最大值75，必须检查墙长12的限制。"],["图象交点与方程的解","x₁=−1，x₂=−4","两个函数值相等时，交点横坐标就是方程的解。已知交点 A(−1,0)、B(−4,3)，直接读出x为−1或−4。验证：直线为 y=−x−1，联立得x²+5x+4=(x+1)(x+4)=0。","方程的解取横坐标，不是交点的纵坐标。"],["系数关系综合判断","④","图中开口向下，所以a<0；对称轴x=1得b=−2a>0，①ab>0错误。根−1关于x=1对称的另一根为3；x=2在两根之间，y(2)=4a+2b+c>0，②错误。代入(−1,0)：a−b+c=0，结合b=−2a得3a+c=0，③错误。④中 y₁−y₂=(x₁−x₂)[a(x₁+x₂)+b]=a(x₁−x₂)(x₁+x₂−2)>0，所以y₁>y₂。","判断结论要区分大于0、小于0、等于0。"],["已知轴和点求解析式","y=−(x+1)²+4=−x²−2x+3","已知对称轴x=−1，设顶点式y=a(x+1)²+k。代入A(−3,0)：4a+k=0；代入B(0,3)：a+k=3。两式相减得3a=−3，a=−1，再求k=4。也可由对称性找另一根1，设y=a(x+3)(x−1)。","有轴优先设顶点式；有根也可设交点式。"],["三种形式与图象性质","(1)顶点(1,−4)，交点(−1,0)、(3,0)；(2)x<−1或x>3；(3)x>1","一般式y=x²−2x−3，配方得顶点式y=(x−1)²−4，因式分解得交点式y=(x+1)(x−3)。顶点式读顶点和对称轴；交点式读两根。开口向上，两根外侧y>0；对称轴右侧递增（也可将增区间写为[1,+∞)）。","三种形式描述同一条抛物线，各自适合读取不同信息。"],["交点式求解析式与区间最值","(1)y=(x+4)(x−2)=x²+2x−8；(2)−9≤y<40","x²系数为1，且根为−4、2，直接设y=(x+4)(x−2)。配方y=(x+1)²−9，顶点(−1,−9)。−1在(−2,6)内，故−9能取到。右端靠近6时y趋近40，但x=6不能取，故y<40。左端对应−8不影响全区间最小值。","顶点在开区间内仍可取到；端点6不取，所以40不取。"],["直线与抛物线联立","(1)m=−1，y₂=x²−2x−3；(2)顶点(1,−4)，轴x=1；(3)x<−1或x>2","把A(−1,0)代入y₁=−x+m：0=1+m，故m=−1。代入抛物线：a−b−3=0，4a+2b−3=−3，解得a=1、b=−2。配方得y₂=(x−1)²−4。比较y₂−y₁=x²−x−2=(x+1)(x−2)，要y₁<y₂，需此积>0，故取两根外侧。","比较上下关系可转成函数差的正负，交点处不满足严格小于。"],["坐标与面积、区间最值","(1)6；(2)x<−1或x>3；(3)−5≤y≤4","令y=0：−(x−3)(x+1)=0，A(−1,0)、B(3,0)，底AB=4。令x=0，得C(0,3)，高为3，面积=4×3÷2=6。开口向下，y<0在两根外侧。配方y=−(x−1)²+4，在[0,4]中顶点给最大值4；端点y(0)=3、y(4)=−5，最小值−5。","区间最值必须同时检查顶点和端点。"],["投篮模型：顶点式建模","(1)y=−(x−4)²/9+4；(2)按题设模型能投中","最高点(4,4)，设y=a(x−4)²+4。出手点(0,20/9)，代入20/9=16a+4，解得a=−1/9。篮圈位置(7,3)，代入x=7得y=−9/9+4=3，说明篮圈中心在轨迹上，按题设模型可投中。","给出最高点时优先设顶点式；计算需保留分数。"],["利润应用","(1)y=−2x+160，30≤x≤60；(2)单价55元，最大利润1250元","由两组数据得斜率(80−100)/(40−30)=−2，再代入(30,100)得截距160。每日利润=每件利润×销量，w=(x−30)(−2x+160)=−2x²+220x−4800=−2(x−55)²+1250。55在[30,60]内，故最大利润1250元。","利润不是售价乘销量；先扣每件成本30元。"],["含参函数综合与配方证明","(1)根为m、m+2；(2)k=−1；(3)p+q=2m²+8≥8","(1)y₁=(x−m)(x−m−2)，令y₁=0得x=m或m+2，两根始终相差2，所以有两个不同交点。(2)配方y₁=[x−(m+1)]²−1，顶点(m+1,−1)。代入y₂=kx+m：−1=k(m+1)+m，整理为k(m+1)=−(m+1)。由m≠−1，可除以m+1，得k=−1。(3)因此y₂=−x+m。相加得y=x²−(2m+3)x+m²+3m。代入x=−1得p=m²+5m+4；代入x=4得q=m²−5m+4。因此p+q=2m²+8≥8，当m=0时等号成立。","原卷解析将y₂误写为−(m+1)，后续展开式也有误。这里已按题干更正为y₂=−x+m，并逐项重新计算。"]]
;

(()=>{
'use strict';
const root=document.querySelector('#basic-list'),filter=document.querySelector('#basic-filter'),today=[1,2,3,4,11,12,15,17,18,19,20],KEY='hh-quadratic-basic-20261103-v1';
let saved={};try{const d=JSON.parse(localStorage.getItem(KEY)||'{}');if(d&&typeof d==='object'&&!Array.isArray(d))saved=d}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const group=n=>n<=10?'choice':n<=16?'fill':'written';
document.querySelector('#panel-10').insertAdjacentHTML('afterbegin','<style>.basic-card{margin-top:24px;scroll-margin-top:95px}.basic-card header{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border:0;margin-bottom:16px}.basic-card header h3{margin:0}.basic-card img{display:block;width:100%;height:auto;background:white}.basic-image{overflow:auto;border:1px solid #e4e9e8;border-radius:10px;padding:12px;background:white}.basic-image img.zoomed{width:150%;max-width:none}.basic-card .basic-note{display:block;width:100%;resize:vertical;min-height:90px;font:inherit;color:var(--ink);border:1px solid var(--line);border-radius:9px;padding:12px;background:#f9fbfa;margin-top:10px}.basic-card details.answer{margin-top:16px}.basic-card .basic-kp{background:var(--soft);padding:9px 14px;border-radius:8px;margin:12px 0;font-size:17px}.basic-card .basic-solution{white-space:pre-line;line-height:2}.basic-jumps{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.basic-jumps a{display:grid;place-items:center;min-width:42px;height:42px;background:white;border:1px solid var(--line);border-radius:8px;text-decoration:none}.basic-card[hidden]{display:none}#panel-10 .toolbar{flex-wrap:wrap}@media(max-width:650px){.basic-card{padding:16px}.basic-image{padding:5px}.basic-card header{display:block}.basic-card header label{display:block;margin-top:10px}}@media print{.basic-jumps,.basic-card textarea,.basic-card .toolbar{display:none}}</style>');
root.innerHTML=BASIC_CROPS.map(q=>{const [kp,answer,why,error]=BASIC_SOLUTIONS[q.n-1],record=saved[q.n]||{};return '<article class="card basic-card" id="basic-q-'+q.n+'" data-basic="'+q.n+'"><header><h3>第 '+q.n+' 题 · '+(q.n<=10?'选择题':q.n<=16?'填空题':'解答题')+'</h3><label class="small">记录 <select data-basic-mark="'+q.n+'"><option value="">未记录</option><option value="done">已完成</option><option value="redo">待重做</option></select></label></header><div class="basic-kp">知识点：'+kp+(today.includes(q.n)?' · 三种形式优先练习':'')+'</div><div class="basic-image"><img src="'+q.src+'" width="'+q.width+'" height="'+q.height+'" loading="lazy" alt="基础检测卷第'+q.n+'题原题和配图，原PDF第'+q.page+'页"></div><div class="toolbar"><button type="button" data-basic-zoom="'+q.n+'">放大原题</button><span class="small muted">原 PDF 第 '+q.page+' 页 · 可放大后横向查看</span></div><label>作答与课堂笔记<textarea class="basic-note" data-basic-note="'+q.n+'" placeholder="写下答案、配方过程或卡住的步骤…">'+escape(record.note||'')+'</textarea></label><details class="answer"><summary>教师解析 · 答案、方法与易错点</summary><h4>正确答案</h4><p>'+answer+'</p><h4>解题方法</h4><p class="basic-solution">'+why.replace(/\。/g,'。\n')+'</p><div class="note '+(q.n===24?'warn':'')+'"><b>'+(q.n===24?'原解析更正':'易错提醒')+'</b><p>'+error+'</p></div></details></article>'}).join('');
const cards=[...root.querySelectorAll('[data-basic]')];
function refresh(){const v=filter.value;let visible=0;for(const c of cards){const n=+c.dataset.basic;c.hidden=!(v==='all'||v==='today'&&today.includes(n)||v===group(n)||v==='redo'&&saved[n]?.mark==='redo');if(!c.hidden)visible++}document.querySelector('#basic-progress').textContent='显示 '+visible+' / 24 · 已完成 '+Object.values(saved).filter(r=>r.mark==='done').length+' · 待重做 '+Object.values(saved).filter(r=>r.mark==='redo').length;document.querySelector('#basic-empty').hidden=visible!==0;document.querySelector('#basic-jumps').innerHTML=cards.filter(c=>!c.hidden).map(c=>'<a href="#'+c.id+'" data-basic-jump="'+c.dataset.basic+'">题'+c.dataset.basic+'</a>').join('');}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved))}catch{}}
root.querySelectorAll('[data-basic-mark]').forEach(el=>{el.value=['done','redo'].includes(saved[el.dataset.basicMark]?.mark)?saved[el.dataset.basicMark].mark:'';el.onchange=()=>{const n=el.dataset.basicMark;saved[n]={...saved[n],mark:el.value};persist();refresh()}});
root.querySelectorAll('[data-basic-note]').forEach(el=>el.oninput=()=>{const n=el.dataset.basicNote;saved[n]={...saved[n],note:el.value};persist()});
root.querySelectorAll('[data-basic-zoom]').forEach(el=>el.onclick=()=>{const im=el.closest('article').querySelector('img'),on=im.classList.toggle('zoomed');el.textContent=on?'恢复原题大小':'放大原题'});
document.querySelector('#basic-jumps').onclick=e=>{const a=e.target.closest('[data-basic-jump]');if(!a)return;e.preventDefault();document.querySelector('#basic-q-'+a.dataset.basicJump).scrollIntoView({behavior:'smooth',block:'start'})};
filter.onchange=refresh;
document.querySelector('#basic-open').onclick=()=>cards.filter(c=>!c.hidden).forEach(c=>c.querySelector('details').open=true);
document.querySelector('#basic-close').onclick=()=>cards.forEach(c=>c.querySelector('details').open=false);
refresh();
})();

